M=""; N=0; for f in $(find internal/convert/testdata/cad -type f ! -name PROVENANCE.md); do N=$((N + 1)); s=$(shasum -a 256 "$f" | cut -d' ' -f1); grep -q "$(basename "$f")" internal/convert/testdata/cad/PROVENANCE.md && grep -q "$s" internal/convert/testdata/cad/PROVENANCE.md || M="$M $f"; done; test "$N" -gt 0 && test -z "$M" && echo PROVENANCE-COMPLETE || { echo "MISSING:$M files=$N"; exit 1; }
